from __future__ import annotations

from pathlib import Path

import pytest
from ds.ai import scripts

GOOD = '''
"""Squares of the first numbers (a test script)."""

from pydantic import BaseModel

LIMIT = 100


class Square(BaseModel, frozen=True):
    n: int
    square: int


def first_squares(count: int = 3) -> list[Square]:
    """The squares of 1..count."""
    return [_square(n) for n in range(1, min(count, LIMIT) + 1)]


def _square(n: int) -> Square:
    return Square(n=n, square=n * n)


def _check(rows: list[Square]) -> str:
    return "" if rows else "no rows"
'''


@pytest.fixture(autouse=True)
def store(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    """Every test gets its own empty scripts folder and run history."""
    monkeypatch.setattr(scripts, "SCRIPTS_DIR", tmp_path / "scripts")
    monkeypatch.setattr(scripts, "RUNS_FILE", tmp_path / "runs.jsonl")
    scripts.clear_runs()
    return tmp_path / "scripts"


def test_a_script_that_keeps_the_rules_is_allowed():
    assert scripts.script_problem(GOOD, "first_squares") == ""


@pytest.mark.parametrize(
    ("change", "why"),
    [
        (("def first_squares(", "def other_name("), "one public function, named as its file"),
        (("def _square(n: int)", "def square(n: int)"), "one public function"),
        (("count: int = 3", "count=3"), "has no type"),
        ((') -> list[Square]:\n    """The squares', '):\n    """The squares'), "no return type"),
        (('    """The squares of 1..count."""\n', ""), "no docstring"),
        (('"""Squares of the first numbers (a test script)."""', ""), "must start with a docstring"),
        (("from pydantic import BaseModel", "import os\nfrom pydantic import BaseModel"), "`import os` isn't allowed"),
        (("LIMIT = 100", "limit = []"), "top level may hold only"),
        (("LIMIT = 100", "LIMIT = 100\nprint(LIMIT)"), "top level may hold only"),
        (("    return Square(n=n", "    global LIMIT\n    return Square(n=n"), "global"),
        (("    return Square(n=n", "    open('/etc/passwd')\n    return Square(n=n"), "`open` isn't allowed"),
        (("    return Square(n=n", "    BaseModel.x = 1\n    return Square(n=n"), "assigning to an attribute"),
        (("    return Square(n=n", "    n.__class__\n    return Square(n=n"), "private or dunder"),
        (
            ("from pydantic import BaseModel", "from ds.ai.extract import from_url\nfrom pydantic import BaseModel"),
            "isn't allowed",
        ),
    ],
)
def test_a_script_that_breaks_a_rule_is_refused(change: tuple[str, str], why: str):
    code = GOOD.replace(*change)
    assert code != GOOD
    assert why in scripts.script_problem(code, "first_squares")
    with pytest.raises(ValueError, match="not saved"):
        scripts.save("first_squares", code)


@pytest.mark.parametrize("name", ["Bad", "x", "extract", "registry", "a-b"])
def test_a_scripts_name_is_snake_case_and_not_a_ds_ai_module(name: str):
    assert "can't be a script's name" in scripts.script_problem(GOOD, name)


def test_saving_writes_the_file_and_the_registry(store: Path):
    path = scripts.save("first_squares", GOOD)
    assert path == store / "first_squares.py"
    [info] = scripts.registry()
    assert info.description == "Squares of the first numbers (a test script)."
    assert info.signature == "first_squares(count: int=3) -> list[Square]"
    text = (store / "registry.md").read_text()
    assert "| `first_squares` | Squares of the first numbers (a test script). |" in text
    assert "TODO: decide the constraints on script files" in text


def test_a_run_validates_the_result_and_is_recorded():
    scripts.save("first_squares", GOOD)
    rows = scripts.run("first_squares", count=2)
    assert [row.square for row in rows] == [1, 4]
    [made] = scripts.runs()
    assert made.ok
    assert made.rows == 2
    assert "first_squares" in scripts.last_runs()
    assert scripts.past_calls("first_squares") == [{"count": 2}]


def test_a_run_reads_the_file_fresh_so_an_edit_applies_at_once(store: Path):
    scripts.save("first_squares", GOOD)
    assert len(scripts.run("first_squares")) == 3
    (store / "first_squares.py").write_text(GOOD.replace("count: int = 3", "count: int = 5"))
    assert len(scripts.run("first_squares")) == 5


def test_two_scripts_with_the_same_private_names_dont_collide():
    other = GOOD.replace("first_squares", "first_cubes").replace("square=n * n", "square=n * n * n")
    scripts.save("first_squares", GOOD)
    scripts.save("first_cubes", other)
    assert scripts.run("first_squares", count=2)[1].square == 4
    assert scripts.run("first_cubes", count=2)[1].square == 8


@pytest.mark.parametrize(
    ("change", "why"),
    [
        (("    return [_square(n) for n", "    raise KeyError('gone')\n    return [_square(n) for n"), "KeyError"),
        (("return Square(n=n, square=n * n)", "return {'n': 'x'}"), "ValidationError"),
        (("range(1, min(count, LIMIT) + 1)", "range(0)"), "its own check says: no rows"),
    ],
)
def test_a_failing_script_says_why(change: tuple[str, str], why: str):
    scripts.save("first_squares", GOOD.replace(*change))
    with pytest.raises(scripts.ScriptFailed) as failed:
        scripts.run("first_squares")
    assert why in failed.value.why
    assert not scripts.runs()[-1].ok


def test_a_missing_script_and_a_hand_edit_that_breaks_the_rules_fail(store: Path):
    with pytest.raises(scripts.ScriptFailed, match="no such script"):
        scripts.run("nothing_here")
    scripts.save("first_squares", GOOD)
    (store / "first_squares.py").write_text(GOOD.replace("LIMIT = 100", "import os"))
    with pytest.raises(scripts.ScriptFailed, match="breaks the script rules"):
        scripts.run("first_squares")
    assert "BROKEN" in scripts.registry_text()


def test_without_a_url_a_failed_script_has_no_fallback():
    scripts.save("first_squares", GOOD.replace("range(1, min(count, LIMIT) + 1)", "range(0)"))
    with pytest.raises(scripts.ScriptFailed):
        scripts.Scripts().first_squares(count=1)


def test_over_the_cap_lists_never_run_scripts_first(monkeypatch: pytest.MonkeyPatch):
    scripts.save("first_squares", GOOD)
    scripts.save("first_cubes", GOOD.replace("first_squares", "first_cubes"))
    assert scripts.over_cap() == []
    scripts.run("first_squares")
    monkeypatch.setattr(scripts, "MAX_DIR_BYTES", 100)
    listed = scripts.over_cap()
    assert [info.id for info, _ in listed] == ["first_cubes", "first_squares"]
    assert listed[0][1] == "never"


def test_delete_removes_the_file_and_its_registry_row(store: Path):
    scripts.save("first_squares", GOOD)
    assert scripts.delete("first_squares")
    assert not scripts.delete("first_squares")
    assert "first_squares" not in (store / "registry.md").read_text()


def test_the_same_rows_are_counted_across_different_model_classes():
    rows = scripts._call(GOOD, "first_squares", {"count": 3})
    expected = scripts._call(GOOD, "first_squares", {"count": 2})  # another class object, same data
    assert scripts._same(rows, expected) == (2, 2)
    assert scripts._same(expected, rows) == (2, 3)


def test_the_committed_registry_is_current(monkeypatch: pytest.MonkeyPatch):
    """registry.md is rebuilt on every save: a script added by hand must rebuild it too."""
    monkeypatch.undo()
    committed = scripts.SCRIPTS_DIR / scripts.REGISTRY_NAME
    assert committed.read_text() == scripts.registry_text(), "run ds.ai.scripts.write_registry()"
